    const fA = tt(A);
    ok(await eventually(() => started(fA)) && await A.evaluate(() => window.__board21.state.wins.get('task-timer:1').connected), 'Task Timer opens and connects');
    // A schedule, made in its editor: Reading (1 min), Snack (2 min).
