    const at = Date.now(), task = { totalMode: 'sum', totalMinutes: 60, tasks: [{ emoji: '⭐', name: 'Reading', minutes: 10, color: '#ff5e57' }], activeIndex: 0, secondsLeft: 600, running: true, endsAt: at + 540e3, alarm: false };
